#[test]
fn agitjo_autoload_contract_exposes_only_setup_without_loading_package() {
    let elisp_form = r##"(list
         (featurep 'agitjo)
         (mapcar
          (lambda (symbol)
            (let ((definition (symbol-function symbol)))
              (list
               symbol
               (autoloadp definition)
               (nth 1 definition)
               (nth 4 definition)
               (commandp symbol))))
          '(agitjo-setup agitjo-push agitjo-post-confirm)))"##;
    let expect = expect![[
        r#"OK (nil ((agitjo-setup t "agitjo" nil nil) (agitjo-push nil nil nil nil) (agitjo-post-confirm nil nil nil nil)))"#
    ]];
    assert_agitjo_autoload_parity(elisp_form, expect);
}

#[test]
fn agitjo_post_mode_real_buffer_lifecycle_sets_markdown_parent_keymap_and_local_config() {
    let elisp_form = r##"(with-temp-buffer
         (setq agitjo-post--pullreq-config 'outer)
         (agitjo-post-mode)
         (setq-local agitjo-post--pullreq-config 'draft)
         (list
          major-mode
          mode-name
          (derived-mode-p 'gfm-mode 'markdown-mode 'text-mode)
          (local-variable-p 'agitjo-post--pullreq-config)
          agitjo-post--pullreq-config
          (key-binding (kbd "C-c C-c"))
          (key-binding (kbd "C-c C-k"))
          (lookup-key (current-local-map) [remap kill-buffer])))"##;
    let expect = expect![[
        r#"OK (agitjo-post-mode "AGitjo-Post" gfm-mode t draft agitjo-post-confirm agitjo-post-cancel agitjo-post-cancel)"#
    ]];
    assert_agitjo_parity(elisp_form, expect);
}
